let damageBonus=0,maxHealth=100;function shopItems(){const options=[];const next=[1,2,3].find(i=>!weapons[i].owned);if(next!==undefined){const w=weapons[next];options.push({icon:'⌁',title:`${w.name}`,desc:`Field-tested ${w.type.toLowerCase()} with a fresh magazine.`,cost:w.price,action:()=>{w.owned=true;equip(next);state.scrap-=w.price;state.reserve+=w.mag*2}})}else{options.push({icon:'✳',title:'HOT LOAD',desc:'Improve your weapon handling. +25% damage, permanently.',cost:70,action:()=>{damageBonus+=.25;state.scrap-=70}})}options.push({icon:'✚',title:'MEDIC KIT',desc:'Restore 45 vitality. No questions asked.',cost:32,action:()=>{state.health=Math.min(maxHealth,state.health+45);state.scrap-=32}});options.push({icon:'⬡',title:'PLATE VEST',desc:'Reinforced plates. Increase max vitality by 25 and heal.',cost:58,action:()=>{maxHealth+=25;state.health=Math.min(maxHealth,state.health+25);state.scrap-=58}});return options}
